root <- dirname(normalizePath(sub('^--file=','',grep('^--file=',commandArgs(FALSE),value=TRUE)[[1]])))
.libPaths(c(file.path(root,'library'),.libPaths()))
stopifnot(requireNamespace('preprocessCore',quietly=TRUE))
library(jsonlite)
joint<-cbind(c(0,0,0,1,2,3,4,9),c(0,2,2,2,6,8,10,15),c(1,1,2,2,2,7,10,12),c(0,0,0,0,1,2,3,8),c(0,1,4,8,10,13,14,20))
dimnames(joint)<-list(paste0('gene_',1:8),c('bulk_1','bulk_2','cell_1','cell_2','cell_3'))
normalized<-preprocessCore::normalize.quantiles(joint,copy=TRUE)
target<-rowMeans(apply(joint,2,sort))
rank_midpoint<-apply(joint,2,function(x) approx(seq_along(target),target,rank(x,ties.method='average'),rule=2)$y)
full_tie_mean<-apply(joint,2,function(x) {
  o<-order(x); v<-x[o]; ans<-numeric(length(x))
  for(t in unique(v)){ii<-which(v==t);ans[o[ii]]<-mean(target[ii])};ans
})
out<-list(provenance=list(R=R.version.string,preprocessCore=as.character(packageVersion('preprocessCore')),preprocessCore_sha='5f4522fcbce0820b4983f453e3d56341da62da85',threading=FALSE),inputs=list(joint_expression=joint,bulk_columns=2L,gene_ids=rownames(joint),observation_ids=colnames(joint)),target=target,normalized=normalized,pearson=cor(normalized[,1:2],normalized[,3:5]),midpoint_rank_interpolation=rank_midpoint,whole_tie_target_mean=full_tie_mean,max_error_midpoint=max(abs(normalized-rank_midpoint)),max_error_whole_tie_mean=max(abs(normalized-full_tie_mean)))
jsonlite::write_json(out,file.path(root,'fixtures','preprocessing_ties.json'),pretty=TRUE,auto_unbox=TRUE,digits=16,matrix='rowmajor')
cat('preprocessCore',as.character(packageVersion('preprocessCore')),'midpoint error',out$max_error_midpoint,'whole-tie error',out$max_error_whole_tie_mean,'\n')
constant<-cbind(rep(0,8),seq_len(8),8:1)
qconst<-preprocessCore::normalize.quantiles(constant)
jsonlite::write_json(list(inputs=constant,normalized=qconst,correlation=suppressWarnings(cor(qconst)),expected_python_behavior='Reject undefined Pearson correlation after normalization; do not replace it by zero.'),file.path(root,'fixtures','preprocessing_constant_column.json'),pretty=TRUE,auto_unbox=TRUE,digits=16,na='string',matrix='rowmajor')
